extra=r'''
function dataBytes(data){const b=atob(data.split(',')[1]);return Uint8Array.from(b,c=>c.charCodeAt(0))}
function zipStore(files){const enc=new TextEncoder(),parts=[],central=[];let offset=0;const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});const crc=bytes=>{let n=0xffffffff;for(const b of bytes)n=crcTable[(n^b)&255]^(n>>>8);return (n^0xffffffff)>>>0};function header(size){const b=new Uint8Array(size);return {b,d:new DataView(b.buffer)}}for(const file of files){const name=enc.encode(file.name),bytes=typeof file.data==='string'?enc.encode(file.data):file.data,c=crc(bytes),h=header(30);h.d.setUint32(0,0x04034b50,true);h.d.setUint16(4,20,true);h.d.setUint16(6,0x800,true);h.d.setUint32(14,c,true);h.d.setUint32(18,bytes.length,true);h.d.setUint32(22,bytes.length,true);h.d.setUint16(26,name.length,true);parts.push(h.b,name,bytes);const z=header(46);z.d.setUint32(0,0x02014b50,true);z.d.setUint16(4,20,true);z.d.setUint16(6,20,true);z.d.setUint16(8,0x800,true);z.d.setUint32(16,c,true);z.d.setUint32(20,bytes.length,true);z.d.setUint32(24,bytes.length,true);z.d.setUint16(28,name.length,true);z.d.setUint32(42,offset,true);central.push(z.b,name);offset+=30+name.length+bytes.length}const centralSize=central.reduce((n,b)=>n+b.length,0),end=header(22);end.d.setUint32(0,0x06054b50,true);end.d.setUint16(8,files.length,true);end.d.setUint16(10,files.length,true);end.d.setUint32(12,centralSize,true);end.d.setUint32(16,offset,true);return new Blob([...parts,...central,end.b],{type:'application/zip'})}
async function exportPreview(){const p=project();if(!p?.scenes.length)return toast('Importe uma panorâmica antes de exportar.');if(audit(p).some(i=>i.level==='erro'))return toast('Corrija os erros da auditoria antes de exportar.');const out=structuredClone(p),files=[];out.scenes.forEach((s,i)=>{const ext=s.image.startsWith('data:image/png')?'png':s.image.startsWith('data:image/webp')?'webp':'jpg';const path=`panos/${i+1}.${ext}`;files.push({name:path,data:dataBytes(s.image)});s.image=path});const branding=structuredClone(state.brand);if(branding.logo){const ext=branding.logo.startsWith('data:image/png')?'png':branding.logo.startsWith('data:image/webp')?'webp':'jpg';files.push({name:'assets/logo.'+ext,data:dataBytes(branding.logo)});branding.logo='assets/logo.'+ext}const data=JSON.stringify({project:out,brand:branding}).replace(/</g,'\\u003c');const runtime=`'use strict'; const $=s=>document.querySelector(s);let adding=false;function pointForm(){};const TOUR=${data};\n${Panorama.toString()}\nlet index=0,engine;const p=TOUR.project;document.title=p.name;$('#brand').textContent=TOUR.brand.name;$('#name').textContent=p.name;if(TOUR.brand.logo){$('#logo').src=TOUR.brand.logo;$('#logo').hidden=false}const menu=$('#scenes');p.scenes.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=s.name;menu.append(o)});function load(i){engine?.destroy();index=i;menu.value=i;$('#scene-name').textContent=p.scenes[i].name;engine=new Panorama($('#pano'),p.scenes[i].image,draw);if(p.transition==='fade'&&!matchMedia('(prefers-reduced-motion:reduce)').matches)$('#pano').animate([{opacity:0},{opacity:1}],{duration:400})}function draw(){const layer=$('#points');layer.innerHTML='';for(const h of p.scenes[index].hotspots){const pos=engine.project(h.yaw,h.pitch);if(!pos)continue;const b=document.createElement('button');b.className='point';b.style.left=pos.x+'px';b.style.top=pos.y+'px';b.title=h.label;b.setAttribute('aria-label',h.label);b.textContent=h.type==='scene'?'↑':h.type==='info'?'i':'↗';b.onclick=()=>{if(h.type==='scene'){const i=p.scenes.findIndex(s=>s.id===h.target);if(i>=0)load(i)}else if(h.type==='info'){ $('#info-title').textContent=h.label;$('#info-content').textContent=h.target;$('#info').showModal()}else{try{const u=new URL(h.target);if(['https:','http:'].includes(u.protocol))window.open(u.href,'_blank','noopener,noreferrer')}catch{}}};layer.append(b)}}menu.onchange=()=>load(+menu.value);$('#prev').onclick=()=>load(Math.max(0,index-1));$('#next').onclick=()=>load(Math.min(p.scenes.length-1,index+1));$('#zoom-in').onclick=()=>engine.zoom(-10);$('#zoom-out').onclick=()=>engine.zoom(10);$('#home').onclick=()=>load(0);$('#full').onclick=()=>document.documentElement.requestFullscreen().catch(()=>{});$('#close-info').onclick=()=>$('#info').close();load(0);`;
const html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MG Tour 360</title><style>*{box-sizing:border-box}body{margin:0;background:#142b26;color:white;font-family:Arial,sans-serif}canvas{display:block;width:100vw;height:100vh;touch-action:none}header{position:fixed;inset:20px 20px auto;display:flex;align-items:center;justify-content:space-between;padding:15px;background:#112c29bb;backdrop-filter:blur(10px);border-radius:6px;gap:15px}header img{max-height:45px;max-width:110px}header small{display:block;margin-top:5px;font-size:11px;color:#d4dfd0}#title{margin-right:auto}select,button{padding:12px;border-radius:6px;border:1px solid #ffffff33;background:#173f35;color:white;cursor:pointer}select{max-width:35vw}nav{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);display:flex;gap:5px;max-width:95vw;padding:7px;background:#102e25bb;border-radius:8px}nav button{border:0;padding:11px}.point{position:fixed;width:40px;height:40px;transform:translate(-50%,-50%);padding:0;border:2px solid #d9f294;border-radius:50%;font-size:22px}dialog{border:0;border-radius:12px;max-width:90vw;padding:25px}dialog::backdrop{background:#102b24aa}#info-content{white-space:pre-wrap}@media(max-width:600px){header{inset:10px 10px auto;padding:11px;font-size:12px}select{font-size:11px;padding:8px}nav button{padding:10px 8px}}</style></head><body><canvas id="pano" aria-label="Panorama 360 graus"></canvas><div id="points"></div><header><img id="logo" alt="Logo" hidden><div id="title"><b id="brand"></b><small id="name"></small><small id="scene-name"></small></div><select id="scenes" aria-label="Escolher ambiente"></select></header><nav><button id="prev" aria-label="Ambiente anterior">←</button><button id="home" aria-label="Início">⌂</button><button id="zoom-in" aria-label="Aproximar">＋</button><button id="zoom-out" aria-label="Afastar">−</button><button id="next" aria-label="Próximo ambiente">→</button><button id="full" aria-label="Tela cheia">⛶</button></nav><dialog id="info"><h2 id="info-title"></h2><p id="info-content"></p><button id="close-info">Fechar</button></dialog><script src="runtime.js"></script></body></html>';
files.push({name:'index.html',data:html},{name:'runtime.js',data:runtime},{name:'project.json',data:JSON.stringify({schema:'mgtour360.project/v1',...out,brand:branding},null,2)},{name:'LEIA-ME.txt',data:'MG Tour 360 — prévia independente v0.1\nExtraia a pasta inteira. Abra index.html em um navegador com WebGL. Mantenha panos e assets junto de index.html e runtime.js.\nEsta prévia usa um player próprio. Não é um projeto nativo 3DVista. Não contém motor ou código da referência Sphere.\nConfira panoramas, hotspots, destinos e dispositivos antes de publicar.\nO JSON inclui referências relativas às imagens deste pacote. O backup do workspace usa imagens incorporadas e deve ser guardado separadamente.\n'});const blob=zipStore(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mg-tour-previa-360.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('ZIP da prévia gerado. Integração 3DVista continua pendente.');}
'''
